<?php declare(strict_types=1);
$sourceHistory=array_values(array_reverse(array_filter($service->history($periodId),static fn(array $event):bool=>in_array($event['payload']['kind'],['source_imported','source_corrected'],true))));if(!$sourceHistory)return;
$sourcePages=(int)ceil(count($sourceHistory)/20);$sourcePageRaw=$_GET['source_history_page']??'1';$sourcePageValid=is_string($sourcePageRaw)&&preg_match('/\A[1-9][0-9]{0,3}\z/D',$sourcePageRaw)&&(int)$sourcePageRaw<=$sourcePages;$sourceHistoryPage=$sourcePageValid?(int)$sourcePageRaw:1;$sourceHistoryUrl=static fn(int $page):string=>url(['view'=>'finance','tab'=>'tax','balance'=>'1','periods'=>'1','period_id'=>$periodId,'source_history_page'=>(string)$page]);
?>
<details class="card" data-period-source-history <?= array_key_exists('source_history_page',$_GET)?'open':'' ?>><summary><?= e($periodText('Übernahmen und Berichtigungen')) ?> (<?= count($sourceHistory) ?>)</summary>
<?php if(!$sourcePageValid): ?><p role="alert"><?= e($periodText('Verlaufsseite dieses Abschlusszeitraums vollständig auswählen.')) ?></p><a class="btn btn-outline" href="<?= e($sourceHistoryUrl(1)) ?>"><?= e($periodText('Verlauf neu öffnen')) ?></a><?php else: ?>
<?php foreach(array_slice($sourceHistory,($sourceHistoryPage-1)*20,20)as$sourceRow):$sourceRowData=$sourceRow['payload']['data'];$sourceRowDescription=$sourceRowData['original_source']['description']??$sourceRowData['proposal']['snapshot']['entry']['description']??$sourceRowData['proposal']['snapshot']['name']??null; ?>
<article><h3><?= e((new DateTimeImmutable($sourceRow['payload']['at']))->setTimezone(new DateTimeZone('Europe/Berlin'))->format('d.m.Y H:i').' · '.$periodText($sourceRow['payload']['kind']==='source_corrected'?'Belegübernahme berichtigt':'Beleg übernommen')) ?></h3><?php if($sourceRowDescription!==null): ?><p><?= e($sourceRowDescription) ?></p><?php endif ?><?php if($sourceRowData['reason']!==''): ?><p><?= e($sourceRowData['reason']) ?></p><?php endif ?><a class="btn btn-outline" data-period-source-history-link="<?= (int)$sourceRow['revision'] ?>" href="<?= e(url(['view'=>'finance','tab'=>'tax','balance'=>'1','periods'=>'1','period_id'=>$periodId,'period_original'=>(string)$sourceRow['revision'],'period_original_sha256'=>$sourceRow['sha256']])) ?>"><?= e($periodText('Diesen ursprünglichen Ausgang lesen')) ?></a></article><?php endforeach ?>
<?php if($sourcePages>1): ?><nav aria-label="<?= e($periodText('Verlauf der Belegübernahmen')) ?>"><p><?= e($periodText('Seite')) ?> <?= $sourceHistoryPage ?> / <?= $sourcePages ?></p><?php if($sourceHistoryPage>1): ?><a class="btn btn-outline" href="<?= e($sourceHistoryUrl($sourceHistoryPage-1)) ?>"><?= e($periodText('Neuere Entscheidungen')) ?></a><?php endif ?><?php if($sourceHistoryPage<$sourcePages): ?><a class="btn btn-outline" href="<?= e($sourceHistoryUrl($sourceHistoryPage+1)) ?>"><?= e($periodText('Frühere Entscheidungen')) ?></a><?php endif ?></nav><?php endif ?><?php endif ?></details>
